INSERT INTO feature VALUES('empty-type','types','The empty type',NULL,'implemented','ordinary',NULL,'`Empty` is user data with no constructor, so a case of no arms over it answers any type and negation is `A -> Empty`; a lambda''s binder matched with no arm is typed by the arrow its position answers, a signature''s or the parameter of the call it is passed to.','core-checker kernel-core surface-lowering','corpus/model/data/empty.gandr','corpus/model/data/empty.gandr',NULL);
